flashExtractionPrompt.responseSchema:
{
  "type": "OBJECT",
  "required": ["thoughtProcess", "clauseSegments", "mappedFields", "unmappedFields", "modifiers", "intent"],
  "properties": {
    "thoughtProcess": {
      "type": "STRING",
      "description": "CoT reasoning before extraction"
    },
    "clauseSegments": {
      "type": "ARRAY",
      "description": "User text segments. Use [] if none.",
      "items": {
        "type": "OBJECT",
        "required": ["text", "type"],
        "properties": {
          "text": { "type": "STRING" },
          "type": { "type": "STRING", "description": "FACT, MODIFIER, or RELATIONSHIP" }
        }
      }
    },
    "mappedFields": {
      "type": "ARRAY",
      "description": "Canonical schema matches. Use [] if none.",
      "items": {
        "type": "OBJECT",
        "required": ["key", "value"],
        "properties": {
          "key":             { "type": "STRING", "description": "Canonical field key" },
          "value":           { "type": "STRING", "description": "Raw user expression, unit attached" },
          "fieldType":       { "type": "STRING", "description": "NUMBER, TEXT, or DATE" },
          "period":          { "type": "STRING", "description": "MONTHLY, ANNUAL, WEEKLY, DAILY, ONE_TIME" },
          "qualifier":       { "type": "STRING", "description": "APPROXIMATE, RANGE, EXACT" },
          "rawSpan":         { "type": "STRING", "description": "Exact user phrase" },
          "relationshipToUser": { "type": "STRING", "description": "SELF, SPOUSE, PARENT, CHILD, HOUSEHOLD — matches profile field schema values" },
          "inferredValue":   { "type": "STRING", "description": "Contextual resolution. Null if unambiguous." },
          "confidenceScore": { "type": "STRING", "description": "HIGH, MEDIUM, LOW" },
          "entityGroupId":   { "type": "STRING", "description": "Existing entityGroupId from sessionProfile.existingEntities (e.g., 'person_1', 'person_2'). Null if this is the first mention of this entity — backend assigns the ID.", "nullable": true },
          "isJit":           { "type": "BOOLEAN", "description": "True for JIT fields from planObject" }
        }
      }
    },
    "unmappedFields": {
      "type": "ARRAY",
      "description": "Non-canonical fields, best-guess keys. Use [] if none.",
      "items": {
        "type": "OBJECT",
        "required": ["key", "value"],
        "properties": {
          "key":             { "type": "STRING", "description": "Best-guess descriptive key" },
          "value":           { "type": "STRING", "description": "Raw user expression" },
          "fieldType":       { "type": "STRING", "description": "NUMBER, TEXT, or DATE" },
          "period":          { "type": "STRING", "description": "MONTHLY, ANNUAL, WEEKLY, DAILY, ONE_TIME" },
          "qualifier":       { "type": "STRING", "description": "APPROXIMATE, RANGE, EXACT" },
          "rawSpan":         { "type": "STRING", "description": "Exact user phrase" },
          "relationshipToUser": { "type": "STRING", "description": "SELF, SPOUSE, PARENT, CHILD, HOUSEHOLD — matches profile field schema values" },
          "inferredValue":   { "type": "STRING", "description": "Contextual resolution. Null if unambiguous." },
          "confidenceScore": { "type": "STRING", "description": "HIGH, MEDIUM, LOW" },
          "entityGroupId":   { "type": "STRING", "description": "Existing entityGroupId from sessionProfile.existingEntities. Null if new entity — backend assigns ID.", "nullable": true }
        }
      }
    },
    "modifiers": {
      "type": "ARRAY",
      "description": "What-if/conditional changes. Use [] if none.",
      "items": {
        "type": "OBJECT",
        "required": ["targetField", "operation"],
        "properties": {
          "targetField":     { "type": "STRING", "description": "Canonical field being modified" },
          "operation":       { "type": "STRING", "description": "INCREASE, DECREASE, INCREASE_PERCENT, DECREASE_PERCENT, REPLACE, COMPARE, REMOVE, CONDITIONAL_SCENARIO" },
          "value":           { "type": "STRING", "description": "Raw delta value" },
          "period":          { "type": "STRING", "description": "MONTHLY, ANNUAL, WEEKLY, DAILY, ONE_TIME" },
          "compareGroup":    { "type": "STRING", "description": "Links COMPARE alternatives" },
          "conditionContext": { "type": "STRING", "description": "Condition text for CONDITIONAL_SCENARIO" },
          "rawSpan":         { "type": "STRING", "description": "Exact user phrase" },
          "inferredValue":   { "type": "STRING", "description": "Contextual resolution of delta" },
          "confidenceScore": { "type": "STRING", "description": "HIGH, MEDIUM, LOW" }
        }
      }
    },
    "intent": {
      "type": "STRING",
      "description": "Per-turn intent for backend routing",
      "enum": ["DATA_INPUT", "WHAT_IF", "CORRECTION", "QUESTION", "GOAL_CHANGE", "GOAL_QUERY", "GREETING", "ACKNOWLEDGMENT"]
    }
  }
}
